import pandas as pd, numpy as np, re

def parse_value(v):
    if v is None or (isinstance(v,float) and np.isnan(v)):
        return np.nan
    s=str(v).strip().strip('"')
    if s=='' or s.lower() in {'nan','none','null'}:
        return np.nan
    if re.search(r'[eE][+-]?\d+$', s):
        try:
            return float(s)
        except:
            pass
    if ',' in s:
        if '.' in s:
            if s.rfind(',') > s.rfind('.'):
                s=s.replace('.','')
                s=s.replace(',','.')
            else:
                s=s.replace(',','')
        else:
            s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

path='/root/environment/data/ckd_lab_data.csv'
df=pd.read_csv(path, dtype=str)
cols=[c for c in df.columns if c!='patient_id']
for c in cols:
    df[c]=df[c].map(parse_value)
df=df.dropna(subset=cols)

checks={
 'Glucose':5,
 'Total_Cholesterol':10,
 'LDL_Cholesterol':10,
 'HDL_Cholesterol':10,
 'Triglycerides':10,
 'Serum_Calcium':4,
 'Phosphorus':2,
 'Total_Bilirubin':5,
 'Uric_Acid':30,
 'Albumin_Serum':10,
 'Free_T4':5,
 'Lactate':2,
}
for c,thr in checks.items():
    s=df[c].astype(float)
    frac=(s<thr).mean()
    print(f"{c:20s} < {thr:>4} : {frac*100:6.2f}%")
