# parser

def parse_value(v):
    if v is None or (isinstance(v,float) and np.isnan(v)):
        return np.nan
    s=str(v).strip().strip('"')
    if s=='' or s.lower() in {'nan','none','null'}:
        return np.nan
    # handle commas and dots
    if re.search(r'[eE][+-]?\d+$', s):
        try:
            return float(s)
        except:
            pass
    if ',' in s:
        if '.' in s:
            # decide whether comma is decimal separator
            if s.rfind(',') > s.rfind('.'):
                s=s.replace('.','')
                s=s.replace(',','.')
            else:
                s=s.replace(',','')
        else:
            s=s.replace(',','.')
    try:
        return float(s)
    except:
